name: Remove SLO label after SLO workflow completes

on:
  pull_request_target:
    types: [opened, synchronize, reopened, closed]

permissions:
  contents: read
  issues: write

jobs:
  remove-slo-label:
    runs-on: ubuntu-latest
    steps:
      - name: Check SLO workflow status and remove label
        uses: actions/github-script@v7
        with:
          script: |
            const pr = context.payload.pull_request;
            if (!pr) {
              console.log('No pull request found.');
              return;
            }
            const label = 'SLO';
            const hasLabel = pr.labels.some(l => l.name === label);
            if (!hasLabel) {
              console.log(`PR #${pr.number} does not have ${label} label.`);
              return;
            }
            const workflows = await github.rest.actions.listRepoWorkflows({
              owner: context.repo.owner,
              repo: context.repo.repo
            });
            const workflow = workflows.data.workflows.find(w => w.name === 'SLO');
            if (!workflow) {
              console.log('SLO workflow not found.');
              return;
            }
            const workflowId = workflow.id;
            const runs = await github.rest.actions.listWorkflowRuns({
              owner: context.repo.owner,
              repo: context.repo.repo,
              workflow_id: workflowId,
              head_branch: pr.head.ref,
              per_page: 1
            });
            const latestRun = runs.data.workflow_runs[0];
            if (!latestRun) {
              console.log('No SLO workflow run found for this PR.');
              return;
            }
            if (!latestRun.conclusion) {
              console.log('SLO workflow run is still in progress.');
              return;
            }
            try {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                name: label
              });
              console.log(`Removed ${label} label from PR #${pr.number}.`);
            } catch (error) {
              if (error.status === 404) {
                console.log(`Label ${label} not found on PR #${pr.number}.`);
              } else {
                throw error;
              }
            }
